using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

public class ServerShipmentService : IShipmentService
{
    private static readonly List<Shipment> _shipments =
    [
        new() { Id = 1, TrackingNumber = "TRK-001234", Origin = "New York, USA", Destination = "London, UK", Status = ShipmentStatus.InTransit, ShippedDate = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(4), CustomerEmail = "customer1@example.com", Description = "Electronics - Laptop" },
        new() { Id = 2, TrackingNumber = "TRK-001235", Origin = "Shanghai, China", Destination = "Los Angeles, USA", Status = ShipmentStatus.OutForDelivery, ShippedDate = DateTime.UtcNow.AddDays(-7), EstimatedDelivery = DateTime.UtcNow.AddDays(1), CustomerEmail = "customer2@example.com", Description = "Furniture - Office Desk" },
        new() { Id = 3, TrackingNumber = "TRK-001236", Origin = "Berlin, Germany", Destination = "Tokyo, Japan", Status = ShipmentStatus.Pending, ShippedDate = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(10), CustomerEmail = "customer3@example.com", Description = "Auto Parts - Engine Components" },
        new() { Id = 4, TrackingNumber = "TRK-001237", Origin = "Sydney, Australia", Destination = "Mumbai, India", Status = ShipmentStatus.Delivered, ShippedDate = DateTime.UtcNow.AddDays(-10), EstimatedDelivery = DateTime.UtcNow.AddDays(-1), CustomerEmail = "customer4@example.com", Description = "Textiles - Cotton Fabric" },
        new() { Id = 5, TrackingNumber = "TRK-001238", Origin = "São Paulo, Brazil", Destination = "Paris, France", Status = ShipmentStatus.Delayed, ShippedDate = DateTime.UtcNow.AddDays(-5), EstimatedDelivery = DateTime.UtcNow.AddDays(3), CustomerEmail = "customer5@example.com", Description = "Food - Coffee Beans" },
        new() { Id = 6, TrackingNumber = "TRK-001239", Origin = "Dubai, UAE", Destination = "Toronto, Canada", Status = ShipmentStatus.InTransit, ShippedDate = DateTime.UtcNow.AddDays(-2), EstimatedDelivery = DateTime.UtcNow.AddDays(5), CustomerEmail = "customer6@example.com", Description = "Medical Supplies" },
    ];

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return Task.FromResult(_shipments.ToList());
    }

    public Task<Shipment?> GetByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = _shipments.FirstOrDefault(s =>
            s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
        return Task.FromResult(shipment);
    }

    public Task UpdateStatusAsync(int id, ShipmentStatus newStatus)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id);
        if (shipment is not null)
            shipment.Status = newStatus;
        return Task.CompletedTask;
    }
}

using Microsoft.AspNetCore.Mvc;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", async (IShipmentService service) =>
        {
            return await service.GetAllShipmentsAsync();
        });

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            var shipment = await service.GetByTrackingNumberAsync(trackingNumber);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        });

        group.MapPut("/{id}/status", async (int id, [FromBody] ShipmentStatus newStatus, IShipmentService service) =>
        {
            await service.UpdateStatusAsync(id, newStatus);
            return Results.NoContent();
        }).RequireAuthorization("DispatcherPolicy");
    }
}

